From 42a88b7572c870b4e5b5856da78789f84a52775b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:37:47 +0100
Subject: [PATCH] ksplash: let the theme fade out before quitting

The splash quit as soon as its last stage was reached, so the busy
indicator froze in place while the closing window faded out. Now ksplash
waits a moment after the last stage, and Breeze fades the indicator out.

BUG: 368942
---
 ksplash/ksplashqml/splashapp.cpp              | 21 +++++++++++++------
 .../org.kde.breeze/contents/splash/Splash.qml | 17 ++++++++++-----
 2 files changed, 27 insertions(+), 11 deletions(-)

diff --git a/ksplash/ksplashqml/splashapp.cpp b/ksplash/ksplashqml/splashapp.cpp
index ba011d183f..ab1a3d9846 100644
--- a/ksplash/ksplashqml/splashapp.cpp
+++ b/ksplash/ksplashqml/splashapp.cpp
@@ -18,6 +18,7 @@
 #include <QLoggingCategory>
 #include <QPixmap>
 #include <QScreen>
+#include <QTimer>

 #include <KConfigGroup>
 #include <KSharedConfig>
@@ -67,8 +68,10 @@ SplashApp::SplashApp(int &argc, char **argv)

     if (!m_testing) {
         QDBusServiceWatcher* watcher = new QDBusServiceWatcher(QStringLiteral("org.kde.PlasmaLoading"), QDBusConnection::sessionBus(), QDBusServiceWatcher::WatchForUnregistration, this);
-        connect(watcher, &QDBusServiceWatcher::serviceUnregistered, this, []() {
-            qGuiApp->quit();
+        connect(watcher, &QDBusServiceWatcher::serviceUnregistered, this, [this]() {
+            if (m_stage < 6) {
+                setStage(6);
+            }
         });
         if (!QDBusConnection::sessionBus().interface()->isServiceRegistered(QStringLiteral("org.kde.PlasmaLoading"))) {
             qGuiApp->quit();
@@ -96,19 +99,25 @@ void SplashApp::timerEvent(QTimerEvent *event)

         setStage(m_stage + 1);

-        m_timer.start(STEP_INTERVAL, this);
+        if (m_stage < 6) {
+            m_timer.start(STEP_INTERVAL, this);
+        }
     }
 }

 void SplashApp::setStage(int stage)
 {
     m_stage = stage;
-    if (m_stage == 6) {
-        QGuiApplication::exit(EXIT_SUCCESS);
-    }
     for (SplashWindow *w : std::as_const(m_windows)) {
         w->setStage(stage);
     }
+    if (m_stage == 6) {
+        m_timer.stop();
+        // Give the theme time to animate out before the windows go away
+        QTimer::singleShot(STEP_INTERVAL, this, [] {
+            QGuiApplication::exit(EXIT_SUCCESS);
+        });
+    }
 }

 void SplashApp::adoptScreen(QScreen *screen)
diff --git a/lookandfeel/org.kde.breeze/contents/splash/Splash.qml b/lookandfeel/org.kde.breeze/contents/splash/Splash.qml
index 71aab92bec..992e4ade0c 100644
--- a/lookandfeel/org.kde.breeze/contents/splash/Splash.qml
+++ b/lookandfeel/org.kde.breeze/contents/splash/Splash.qml
@@ -16,11 +16,8 @@ Rectangle {
     onStageChanged: {
         if (stage == 2) {
             introAnimation.running = true;
-        } else if (stage == 5) {
-            introAnimation.target = busyIndicator;
-            introAnimation.from = 1;
-            introAnimation.to = 0;
-            introAnimation.running = true;
+        } else if (stage == 6) {
+            busyIndicatorOutAnimation.running = true;
         }
     }

@@ -99,4 +96,14 @@ Rectangle {
         duration: Kirigami.Units.veryLongDuration * 2
         easing.type: Easing.InOutQuad
     }
+
+    OpacityAnimator {
+        id: busyIndicatorOutAnimation
+        running: false
+        target: busyIndicator
+        from: 1
+        to: 0
+        duration: Kirigami.Units.longDuration
+        easing.type: Easing.InOutQuad
+    }
 }
